<?php
declare(strict_types=1);
require_once __DIR__.'/../includes/bootstrap.php';
$pageTitle='Calendar';
$monthParam=(string)($_GET['month']??date('Y-m'));$month=DateTimeImmutable::createFromFormat('!Y-m-d',$monthParam.'-01');
if(!$month||$month->format('Y-m')!==$monthParam){$month=new DateTimeImmutable('first day of this month');}
$start=$month->modify('first day of this month');$gridStart=$start->modify('-'.((int)$start->format('N')-1).' days');$gridEnd=$month->modify('last day of this month');$gridEnd=$gridEnd->modify('+'.(7-(int)$gridEnd->format('N')).' days');
$st=$pdo->prepare('SELECT entry_date, COUNT(*) total FROM daily_entries WHERE entry_date BETWEEN ? AND ? GROUP BY entry_date');$st->execute([$gridStart->format('Y-m-d'),$gridEnd->format('Y-m-d')]);$counts=[];foreach($st->fetchAll() as $r)$counts[$r['entry_date']]=(int)$r['total'];
$st=$pdo->prepare('SELECT entry_date,title,category,mood FROM daily_entries WHERE entry_date BETWEEN ? AND ? ORDER BY entry_date, created_at');$st->execute([$gridStart->format('Y-m-d'),$gridEnd->format('Y-m-d')]);$byDate=[];foreach($st->fetchAll() as $r)$byDate[$r['entry_date']][]=$r;
$total=(int)$pdo->query("SELECT COUNT(*) FROM daily_entries WHERE entry_date >= DATE_FORMAT(CURDATE(), '%Y-%m-01') AND entry_date < DATE_ADD(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 1 MONTH)")->fetchColumn();
include __DIR__.'/../includes/header.php';
?>
<section class="module-heading"><div><p class="eyebrow">YOUR DAYS, AT A GLANCE</p><h1>Life <em>calendar.</em></h1><p class="module-intro">A calm overview of the days you’ve made memories and notes.</p></div><a class="btn btn-gold" href="journal.php?date=<?=e(date('Y-m-d'))?>">＋ New journal entry</a></section>
<section class="media-stats journal-stats"><article class="stat-card"><div class="stat-top"><span class="stat-icon">▦</span><span class="stat-label">THIS MONTH</span></div><div class="stat-value"><?=$total?></div><div class="stat-foot">Journal entries this month</div></article><article class="stat-card"><div class="stat-top"><span class="stat-icon">✦</span><span class="stat-label">MONTH VIEW</span></div><div class="stat-value"><?=e($month->format('M'))?></div><div class="stat-foot"><?=e($month->format('Y'))?></div></article></section>
<section class="panel calendar-panel"><div class="calendar-head"><div><p class="eyebrow">MAKE ROOM FOR WHAT MATTERS</p><h2><?=e($month->format('F Y'))?></h2></div><div class="calendar-nav"><a class="btn btn-outline btn-small" href="calendar.php?month=<?=e($month->modify('-1 month')->format('Y-m'))?>">‹ Previous</a><a class="btn btn-outline btn-small" href="calendar.php">Today</a><a class="btn btn-outline btn-small" href="calendar.php?month=<?=e($month->modify('+1 month')->format('Y-m'))?>">Next ›</a></div></div>
<div class="calendar-grid calendar-weekdays"><?php foreach(['Mon','Tue','Wed','Thu','Fri','Sat','Sun'] as $day):?><div class="calendar-weekday"><?=e($day)?></div><?php endforeach;?></div><div class="calendar-grid calendar-days"><?php for($d=$gridStart;$d<=$gridEnd;$d=$d->modify('+1 day')):$key=$d->format('Y-m-d');$inMonth=$d->format('m')===$month->format('m');$isToday=$key===date('Y-m-d');$dayEntries=$byDate[$key]??[];?><a class="calendar-day <?=!$inMonth?'outside-month':''?> <?=$isToday?'is-today':''?> <?=count($dayEntries)?'has-entries':''?>" href="journal.php?date=<?=e($key)?>"><span class="calendar-day-number"><?=$d->format('j')?></span><?php if($dayEntries):?><span class="calendar-entry-count"><?=count($dayEntries)?> <?=count($dayEntries)===1?'entry':'entries'?></span><span class="calendar-entry-preview"><?php foreach(array_slice($dayEntries,0,2) as $de):?><span><?=e($de['title'])?></span><?php endforeach;?></span><?php endif;?></a><?php endfor;?></div><p class="chart-note">Select any date to read existing notes or add a new journal entry.</p></section>
<?php include __DIR__.'/../includes/footer.php';?>
